<?php
declare(strict_types=1);
final class PCChatPreferenceRepository {
 public static function member(PDO $p,int $cid,int $uid):bool{$s=$p->prepare('SELECT 1 FROM conversation_members WHERE conversation_id=? AND user_id=? LIMIT 1');$s->execute([$cid,$uid]);return (bool)$s->fetchColumn();}
 public static function preferences(PDO $p,int $uid):array{$s=$p->prepare('SELECT cp.conversation_id,cp.is_pinned,cp.is_archived,cp.muted_until,cp.updated_at FROM chat_preferences cp JOIN conversation_members cm ON cm.conversation_id=cp.conversation_id AND cm.user_id=cp.user_id WHERE cp.user_id=? ORDER BY cp.is_pinned DESC,cp.updated_at DESC LIMIT 500');$s->execute([$uid]);return array_map(static fn(array $r):array=>['conversation_id'=>(string)$r['conversation_id'],'pinned'=>(bool)$r['is_pinned'],'archived'=>(bool)$r['is_archived'],'muted_until'=>$r['muted_until'],'updated_at'=>$r['updated_at']],$s->fetchAll());}
 public static function setPreferences(PDO $p,int $uid,int $cid,array $d):array{if(!self::member($p,$cid,$uid))return ['status'=>404,'body'=>['ok'=>false,'error'=>'conversation_not_found']];$s=$p->prepare('INSERT INTO chat_preferences (user_id,conversation_id,is_pinned,is_archived,muted_until) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE is_pinned=VALUES(is_pinned),is_archived=VALUES(is_archived),muted_until=VALUES(muted_until)');$s->execute([$uid,$cid,(int)$d['pinned'],(int)$d['archived'],$d['muted_until']]);return ['status'=>200,'body'=>['ok'=>true,'conversation_id'=>(string)$cid,'pinned'=>$d['pinned'],'archived'=>$d['archived'],'muted_until'=>$d['muted_until']]];}
 public static function folders(PDO $p,int $uid):array{$s=$p->prepare('SELECT f.id,f.name,f.position,f.created_at,COUNT(i.conversation_id) item_count FROM chat_folders f LEFT JOIN chat_folder_items i ON i.folder_id=f.id WHERE f.user_id=? GROUP BY f.id,f.name,f.position,f.created_at ORDER BY f.position,f.id');$s->execute([$uid]);return array_map(static fn(array $r):array=>['id'=>(string)$r['id'],'name'=>$r['name'],'position'=>(int)$r['position'],'item_count'=>(int)$r['item_count'],'created_at'=>$r['created_at']],$s->fetchAll());}
 public static function createFolder(PDO $p,int $uid,string $name):array{$s=$p->prepare('SELECT COUNT(*) FROM chat_folders WHERE user_id=?');$s->execute([$uid]);if((int)$s->fetchColumn()>=30)return ['status'=>409,'body'=>['ok'=>false,'error'=>'folder_limit_reached']];$s=$p->prepare('SELECT id FROM chat_folders WHERE user_id=? AND name=?');$s->execute([$uid,$name]);if($s->fetchColumn())return ['status'=>409,'body'=>['ok'=>false,'error'=>'folder_name_exists']];$s=$p->prepare('INSERT INTO chat_folders (user_id,name) VALUES (?,?)');$s->execute([$uid,$name]);return ['status'=>201,'body'=>['ok'=>true,'folder'=>['id'=>(string)$p->lastInsertId(),'name'=>$name,'item_count'=>0]]];}
 public static function deleteFolder(PDO $p,int $uid,int $id):array{$s=$p->prepare('DELETE FROM chat_folders WHERE id=? AND user_id=?');$s->execute([$id,$uid]);return ['status'=>200,'body'=>['ok'=>true,'deleted'=>$s->rowCount()>0]];}
 public static function addItem(PDO $p,int $uid,int $folder,int $cid):array{$s=$p->prepare('SELECT id FROM chat_folders WHERE id=? AND user_id=?');$s->execute([$folder,$uid]);if(!$s->fetchColumn())return ['status'=>404,'body'=>['ok'=>false,'error'=>'folder_not_found']];if(!self::member($p,$cid,$uid))return ['status'=>404,'body'=>['ok'=>false,'error'=>'conversation_not_found']];$p->prepare('INSERT IGNORE INTO chat_folder_items (folder_id,conversation_id) VALUES (?,?)')->execute([$folder,$cid]);return ['status'=>200,'body'=>['ok'=>true,'added'=>true]];}
 public static function removeItem(PDO $p,int $uid,int $folder,int $cid):array{$s=$p->prepare('SELECT id FROM chat_folders WHERE id=? AND user_id=?');$s->execute([$folder,$uid]);if(!$s->fetchColumn())return ['status'=>404,'body'=>['ok'=>false,'error'=>'folder_not_found']];$p->prepare('DELETE FROM chat_folder_items WHERE folder_id=? AND conversation_id=?')->execute([$folder,$cid]);return ['status'=>200,'body'=>['ok'=>true,'removed'=>true]];}
}
